use std::{fs,path::{Path,PathBuf},io::{BufRead,BufReader},process::{Command,Stdio},collections::{BTreeMap,BTreeSet}};use serde_json::{Value,json};use sha2::{Sha256,Digest};
const R:&str="/home/ubuntu/src/zopro-perf-work/group-profile216";
fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
include!("sampling.rs");include!("metadata.rs");
fn timestamp(s:&str)->u64{let(a,b)=s.trim_end_matches(':').split_once('.').unwrap();assert!(b.len()<=9&&b.bytes().all(|b|b.is_ascii_digit()));a.parse::<u64>().unwrap().checked_mul(1_000_000_000).unwrap().checked_add(b.parse::<u64>().unwrap()*10u64.pow(9-b.len()as u32)).unwrap()}
fn sync_bounds(sync:&Value)->(u64,u64){let mut lo=0;let mut hi=u64::MAX;for label in["before","after"]{let pairs=sync[label].as_array().unwrap();assert_eq!(pairs.len(),8);for p in pairs{let v:Vec<u64>=serde_json::from_value(p.clone()).unwrap();assert_eq!(v.len(),3);assert!(v[2]>=v[0]&&v[1]>=v[2]);lo=lo.max(v[1]-v[2]);hi=hi.min(v[1]-v[0]);}}assert!(lo<=hi,"nonintersectingclockbounds");assert!(hi-lo<=5000,"uncertainty>{}ns",hi-lo);(lo,hi)}
fn loss(p:&str){assert!(Path::new(p).starts_with(r("perf")));let mut child=Command::new("/usr/bin/perf").args(["script","-D","-i",p]).stdout(Stdio::piped()).spawn().unwrap();let(mut lost,mut throttle,mut lines)=(vec![],vec![],0);for l in BufReader::new(child.stdout.take().unwrap()).lines(){let l=l.unwrap();lines+=1;if l.contains("PERF_RECORD_LOST"){lost.push(l.clone());}if l.contains("PERF_RECORD_THROTTLE")||l.contains("PERF_RECORD_UNTHROTTLE"){throttle.push(l);}}assert!(child.wait().unwrap().success());println!("{}",json!({"zero_lost":lost.is_empty(),"zero_throttle":throttle.is_empty(),"lost":lost,"throttle":throttle,"decoded_lines":lines}));}
fn output(phase:&str,name:&str)->String{let d=r(format!("{phase}-run/{name}"));let e=read(d.join("exit.json"));assert_eq!(e["returncode"],0);for s in["stdout","stderr"]{assert_eq!(hash(d.join(format!("{s}.log"))),e[format!("{s}_sha256")]);}fs::read_to_string(d.join("stdout.log")).unwrap()}
fn finish(smoke_only:bool){let mut results=vec![];let mut allqualified=true;let mut pooled=BTreeMap::<bool,u64>::new();for j in read(r("jobs.json")).as_array().unwrap(){let smoke=j["smoke"]==true;if smoke_only&&!smoke{continue;}let name=j["name"].as_str().unwrap();let phase=if smoke{"smoke"}else{"main"};let out=output(phase,name);let syncs=out.lines().filter_map(|l|l.strip_prefix("CLOCKSYNC ")).map(|s|serde_json::from_str::<Value>(s).unwrap()).collect::<Vec<_>>();assert_eq!(syncs.len(),1);let sync=&syncs[0];let(offlo,offhi)=sync_bounds(sync);let pid=sync["pid"].as_u64().unwrap()as u32;let summary:Value=serde_json::from_str(out.lines().find_map(|l|l.strip_prefix("SUMMARY ")).unwrap()).unwrap();let workers=summary["placement_before"]["worker_rows"].as_array().unwrap().iter().map(|w|(w["tid"].as_u64().unwrap()as u32,w["index"].as_u64().unwrap()as u32)).collect::<BTreeMap<_,_>>();let tag_tid=workers.iter().map(|(&t,&i)|(i as u64+1,t)).collect::<BTreeMap<_,_>>();let mut intervals=BTreeMap::<u32,Vec<(u64,u64)>>::new();let mut cpu_ns=0u64;let mut cycles=vec![];let mut instr=vec![];let mut n=0;
for l in out.lines().filter_map(|l|l.strip_prefix("PHASE ")){let v:Value=serde_json::from_str(l).unwrap();let e:Vec<u64>=serde_json::from_value(v["events"].clone()).unwrap();let c:Vec<u64>=serde_json::from_value(v["group_cpu"].clone()).unwrap();let p:Vec<u64>=serde_json::from_value(v["group_pmu"].clone()).unwrap();assert_eq!(c[2],c[3]);let tid=tag_tid[&c[2]];assert!(e[11]>=e[10]);intervals.entry(tid).or_default().push((e[10],e[11]));cpu_ns+=c[1]-c[0];cycles.push((p[1]-p[0])as f64);instr.push((p[3]-p[2])as f64);n+=1;}
assert_eq!(n,j["rounds"].as_u64().unwrap());for v in intervals.values(){for pair in v.windows(2){assert!(pair[0].1<=pair[1].0);}}
if j["sampled"]!=true{results.push(json!({"name":name,"boolean":j["boolean"],"sampled":false,"smoke":smoke,"block":j["block"],"sync_width_ns":offhi-offlo,"group_CPU_ms":cpu_ns as f64/n as f64/1e6,"cycles":median(&cycles),"instructions":median(&instr)}));continue;}
let postphase=if smoke{"smoke"}else{"verify"};let attrs=output(postphase,&format!("events-{name}"));for needle in["cpu-clock:u","type: 1 (software)","config: 0","1000000","IP","TID","TIME","CPU","PERIOD","clockid: 1"]{assert!(attrs.contains(needle),"missingattr {needle}");}assert!(!attrs.contains("freq: 1"));let meta=output(postphase,&format!("metadata-{name}"));let(owner,allowed)=profile_owners(&meta,j["binary"].as_str().unwrap());assert_eq!(owner,pid);assert!(workers.keys().all(|t|allowed.contains(t)));let decoded=output(postphase,&format!("decode-{name}"));let loss:Value=serde_json::from_str(output(postphase,&format!("loss-{name}")).trim()).unwrap();let mut total=0;let mut unknown=0;let mut scoped=0;let mut scoped_unknown=0;let mut ambiguous=0;let mut symbols=BTreeMap::<String,u64>::new();let mut bins=BTreeMap::<(String,u64),u64>::new();let mut scoped_rows=vec![];
for line in decoded.lines(){let Some((proc,tid,cpu,period,_))=sample(line)else{continue;};assert_eq!(proc,pid);assert!(allowed.contains(&tid));assert_eq!(period,1_000_000);if let Some(&index)=workers.get(&tid){assert_eq!(cpu,index);}else{assert_eq!(tid,pid);assert!(cpu<j["workers"].as_u64().unwrap()as u32);}let f=line.split_whitespace().collect::<Vec<_>>();let time=timestamp(f[2]);let ip=u64::from_str_radix(f[4].trim_start_matches("0x"),16).unwrap();let raw=f[5..].join(" ");let(base,offset)=if let Some((b,v))=raw.rsplit_once("+0x"){(b,u64::from_str_radix(v,16).unwrap())}else{(raw.as_str(),0)};let symbol=rustc_demangle::try_demangle(base).map(|d|format!("{d:#}")).unwrap_or_else(|_|base.into());total+=1;unknown+=u64::from(symbol.starts_with("[unknown]"));let Some(spans)=intervals.get(&tid)else{continue;};let at=spans.partition_point(|&(s,_)|s+offlo<=time);if at==0{continue;}let(s,e)=spans[at-1];let possible=time>=s+offlo&&time<e+offhi;if !possible{continue;}let definite=time>=s+offhi&&time<e+offlo;if !definite{ambiguous+=1;continue;}scoped+=1;scoped_unknown+=u64::from(symbol.starts_with("[unknown]"));*symbols.entry(symbol.clone()).or_default()+=1;*bins.entry((symbol.clone(),offset/64*64)).or_default()+=1;scoped_rows.push(json!({"tid":tid,"cpu":cpu,"time_ns":time,"ip":format!("{ip:x}"),"symbol":symbol,"offset":offset,"period":period}));}
let unk=unknown as f64/total.max(1)as f64;let sunk=scoped_unknown as f64/scoped.max(1)as f64;let amb=ambiguous as f64/(scoped+ambiguous).max(1)as f64;let quality=loss["zero_lost"]==true&&loss["zero_throttle"]==true&&(smoke||total>=1000&&scoped>=100&&unk<=0.05&&sunk<=0.05&&amb<=0.01);allqualified&=quality;if !smoke{*pooled.entry(j["boolean"]==true).or_default()+=scoped;}
let mut symbols=symbols.into_iter().map(|(s,c)|json!({"symbol":s,"samples":c,"CPU_ms_per_proof_estimate":c as f64/n as f64})).collect::<Vec<_>>();symbols.sort_by_key(|v|std::cmp::Reverse(v["samples"].as_u64().unwrap()));let mut bins=bins.into_iter().map(|((s,o),c)|json!({"symbol":s,"offset64":o,"samples":c})).collect::<Vec<_>>();bins.sort_by_key(|v|std::cmp::Reverse(v["samples"].as_u64().unwrap()));let record=json!({"name":name,"boolean":j["boolean"],"sampled":true,"smoke":smoke,"block":j["block"],"qualified":quality,"samples":total,"unknown_fraction":unk,"G2_scoped":scoped,"scoped_unknown_fraction":sunk,"boundary_ambiguous":ambiguous,"sync_width_ns":offhi-offlo,"offset_bounds_ns":[offlo,offhi],"PID":pid,"assigned_PID_TID_CPU_and_MMAP":true,"zero_lost":loss["zero_lost"],"zero_throttle":loss["zero_throttle"],"group_CPU_ms":cpu_ns as f64/n as f64/1e6,"cycles":median(&cycles),"instructions":median(&instr),"symbols":symbols,"bins64":bins,"perf_data_sha256":hash(j["data"].as_str().unwrap())});let path=r(format!("{name}.scoped-samples.json"));let encoded=serde_json::to_vec(&scoped_rows).unwrap();if path.exists(){assert!(smoke,"only smoke output may already exist");assert_eq!(fs::read(&path).unwrap(),encoded,"existing smoke output changed");}else{fs::write(path,encoded).unwrap();}results.push(record);
}
let ready=if smoke_only{allqualified}else{allqualified&&[false,true].iter().all(|b|pooled.get(b).copied().unwrap_or(0)>=400)&&read(r("result.json"))["ready_to_interpret"]==true&&read(r("pmu-result.json"))["quality_pass"]==true};let result=json!({"qualified":ready,"profile_quality":allqualified,"smoke":smoke_only,"diagnostic_only":true,"rows":results,"pooled_scoped_samples":pooled.iter().map(|(b,n)|(b.to_string(),*n)).collect::<BTreeMap<_,_>>(),"no_adoption_claim":true});let p=r(if smoke_only{"profile-smoke.json"}else{"profile-result.json"});assert!(!p.exists());fs::write(p,serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("Scopedprofilesqualified={ready},quality={allqualified},pooled={pooled:?}");assert!(ready,"profilingqualityfailed, preserveandreportinconclusive");}
#[cfg(test)]mod tests{use super::*;#[test]fn exact_timestamp_and_scoping_boundaries(){assert_eq!(timestamp("1572084.339232676:"),1572084339232676);assert_eq!(timestamp("1.1:"),1_100_000_000);let(lo,hi)=(100u64,110u64);let(s,e)=(1000,2000);let definite=|t|t>=s+hi&&t<e+lo;assert!(!definite(1100));assert!(definite(1110));assert!(definite(2099));assert!(!definite(2100));}#[test]fn clock_bounds_intersect_without_float(){let sync=json!({"before":vec![[1,101,4];8],"after":vec![[50,151,54];8]});assert_eq!(sync_bounds(&sync),(97,100));}}
fn main(){match std::env::args().nth(1).as_deref(){Some("loss")=>loss(&std::env::args().nth(2).unwrap()),Some("smoke")=>finish(true),Some("finish")=>finish(false),_=>panic!()}}
